import * as React from "react";
import { Link } from "gatsby";
import { get } from "lodash";
import { Container, Segment, Label, Grid, Card, Image, Comment } from "semantic-ui-react";
import { MarkdownRemark, MarkdownRemarkConnection, Site } from "../graphql-types";
import { DiscussionEmbed } from "disqus-react";
import {withLayout, LayoutProps} from "../components/Layout";
import { graphql } from "gatsby";
import { GatsbyImage, getImage, getSrc } from "gatsby-plugin-image";
import HtmlAstRenderer from "../components/HtmlAstRenderer";

interface BlogPostProps extends LayoutProps {
  data: {
    post: MarkdownRemark;
    recents: MarkdownRemarkConnection;
    site: Site
  };
}

const BlogPostPage = (props: BlogPostProps) => {
  const { frontmatter, id, htmlAst, timeToRead } = props.data.post;

  const tags = props.data.post.frontmatter.tags
    .map((tag) => <Label key={tag}><Link to={`/blog/tags/${tag}/`}>{tag}</Link></Label>);

  const recents = props.data.recents.edges
    .map(({ node }) => {
      const recentAvatar = get(node, "frontmatter.author.avatar.childImageSharp.gatsbyImageData", {});
      const recentCover = get(node, "frontmatter.image.childImageSharp.gatsbyImageData", {});
      const extra = (
        <Comment.Group>
          <Comment>
            <Comment.Content>
              <Comment.Avatar alt="Avatar" src={getSrc(recentAvatar)} />
              <Comment.Author style={{ fontWeight: 400 }}>
                {node.frontmatter.author.jsonId}
              </Comment.Author>
              <Comment.Metadata style={{ margin: 0 }}>
                {node.timeToRead} min read
              </Comment.Metadata>
            </Comment.Content>
          </Comment>
        </Comment.Group>
      );

      return (
        <div key={node.fields.slug} style={{ paddingBottom: "1em" }}>
          <Card as={Link}
            to={node.fields.slug}
            image={getSrc(recentCover)}
            header={node.frontmatter.title}
            extra={extra}
          />
        </div>
      );
    });

  const cover = get(frontmatter, "image.childImageSharp.gatsbyImageData", {});
  return (
    <Container text>
      <Card fluid key={id}>
        {cover.layout && <GatsbyImage alt="cover image" image={cover} />}
        <Card.Content>
          <Card.Header>
            {frontmatter.title}  
          </Card.Header>
          <Card.Meta>
            <span>{frontmatter.author.jsonId}</span>
            <span>{frontmatter.author.bio}</span>
            <span>{timeToRead} min. read</span>
            <div className="tags" style={{display: "inline-block"}}>{tags}</div>
          </Card.Meta>
        </Card.Content>
        <Card.Content className="markdown">
          <HtmlAstRenderer htmlAst={htmlAst} />
        </Card.Content>
      </Card>

      {props.data.site
        && props.data.site.siteMetadata
        && props.data.site.siteMetadata.disqus
        && <Segment basic>
            <DiscussionEmbed shortname={props.data.site.siteMetadata.disqus} config={{}}/>
        </Segment>
      }

      <Grid padded centered>
        {recents}
      </Grid>

      <style jsx>{`
      :global(.no-margin) {
        margin: 0 !important;
      }
      `}</style>
    </Container>
  );
};

export default withLayout(BlogPostPage);

export const pageQuery = graphql`query TemplateBlogPost($slug: String!) {
  site: site {
    siteMetadata {
      disqus
    }
  }
  post: markdownRemark(fields: {slug: {eq: $slug}}) {
    htmlAst
    excerpt
    timeToRead
    fields {
      slug
    }
    frontmatter {
      tags
      author {
        jsonId
        bio
        twitter
        avatar {
          childImageSharp {
            gatsbyImageData(layout: FIXED, width: 80, height: 80, quality: 100)
          }
        }
      }
      title
      updatedDate(formatString: "MMM D, YYYY")
      image {
        childImageSharp {
          gatsbyImageData(layout: FIXED, width: 700, height: 300, quality: 100)
        }
      }
    }
  }
  recents: allMarkdownRemark(
    filter: {fields: {slug: {ne: $slug}}, frontmatter: {draft: {ne: true}}, fileAbsolutePath: {regex: "/blog/"}}
    sort: {frontmatter: {updatedDate: DESC}}
    limit: 4
  ) {
    edges {
      node {
        id
        fields {
          slug
        }
        timeToRead
        frontmatter {
          title
          image {
            childImageSharp {
              gatsbyImageData(layout: FIXED, width: 300, height: 100)
            }
          }
          author {
            jsonId
            avatar {
              childImageSharp {
                gatsbyImageData(layout: FIXED, width: 36, height: 36)
              }
            }
          }
        }
      }
    }
  }
}`;
